import forgelib as F
G = F.make(slug="the-forge-updates", order=24, kw="the forge update",
 title="The Forge Update History & Is The Forge Dying? (2026)",
 h1="The Forge Update History: Every Major Update, and Is The Forge Dying?",
 desc="The Forge update history from launch to Halloween & Guilds 2026, the Orc update Fridge predicted, player counts today, and whether The Forge is really dying.",
 kw2=["the forge new update","is the forge dying","the forge update log","the forge next update","the forge player count"],
 related=["the-forge-codes","the-forge-races-guide","the-forge-island-3-guide","the-forge-beginners-guide"],
 ids=["ACN2Qh7ivf4","CxDkYNxtfHY"],
 lead="In December 2025, Fridge predicted that the next <strong>The Forge update</strong> would be \"insane\" and bring Orcs. In January 2026, he asked whether The Forge was dying. Ten months later, here's how both calls held up, with the full update history from the Forge Wiki.",
 heading="Watch Fridge's The Forge News Videos",
 sections=[
 ("history","Every Major The Forge Update","""<div class="table-wrap"><table><caption>The Forge major versions (Forge Wiki Version History)</caption><thead><tr><th scope="col">Version</th><th scope="col">Update</th><th scope="col">Date</th></tr></thead><tbody>
<tr><td>1.00</td><td>Release</td><td>November 27, 2025</td></tr><tr><td>1.01</td><td>Weekend Events</td><td>December 6, 2025</td></tr>
<tr><td>1.02</td><td>Frostspire Expanse (Island 3)</td><td>December 25, 2025</td></tr><tr><td>1.03</td><td>Raven Cave Update</td><td>January 3, 2026</td></tr>
<tr><td>1.04</td><td>The Maze Update</td><td>January 11, 2026</td></tr><tr><td>1.05</td><td>Forge Locking Update</td><td>January 18, 2026</td></tr>
<tr><td>1.06</td><td>Crimson Sakura Isles (Island 4)</td><td>February 22, 2026</td></tr><tr><td>1.07</td><td>Void Cave &amp; World Events</td><td>May 29, 2026</td></tr>
<tr><td>1.08</td><td>Molds &amp; Raids</td><td>September 5, 2026</td></tr><tr><td>1.08.1</td><td>New Races &amp; Questboard</td><td>October 10, 2026</td></tr>
<tr><td>1.09</td><td>Halloween &amp; Guilds</td><td>October 20, 2026</td></tr></tbody></table></div>
<p>Smaller patches added Private Servers (December 13, 2025), the Mailbox (January 21, 2026) and a Low-Detail Mode (June 14, 2026).</p>"""),
 ("orcs","Did the Orcs Arrive?","""<p>Yes. Fridge's December 17, 2025 Short teased Orcs. The current race list includes the <strong>Orc</strong> (Rare, 7.5%: +10% Physical Damage and +15% Health) and the <strong>Orc Lord</strong> (Mythical, 0.25%: +40% Physical Damage and a Titanic Earthquake slam). Common and Elite Orcs also appear as enemies on the wiki. See them in our <a href="the-forge-races-guide.html">races guide</a>.</p>"""),
 ("dying","Is The Forge Dying?","""<p>Fridge's January 6, 2026 video looked at why players thought the game was losing steam after its huge launch. Here's where it stands now:</p>
<ul><li><strong>Players:</strong> about <strong>22,800 online</strong> on November 11, 2026, according to Roblox's own game data.</li><li><strong>Visits:</strong> over <strong>1.04 billion</strong>.</li><li><strong>Updates:</strong> five major updates since that video, including a whole new island, with the latest less than a month ago.</li></ul>
<p>The game has cooled from its launch peak, and the gap between May and September 2026 was its longest without a major update. Still, 22,800 concurrent players is a large audience for a Roblox RPG. In early November 2026, the developers handed out apology codes after downtime: <code>SORRYFORSHUTDOWNN!</code>, <code>AIDASAYSSORRY</code> and <code>FORGECOMEBACK</code>. Grab them on our <a href="the-forge-codes.html">The Forge codes</a> page.</p>"""),
 ("next","What to Expect Next","""<p>Updates have landed every few weeks to few months, usually with new codes. Each update tends to add a new area, new ores and new recipes. Bookmark our <a href="the-forge-codes.html">codes page</a>, which we refresh regularly, and the <a href="tag-the-forge.html">The Forge guides</a> list.</p>""")],
 faq=[("What is the latest The Forge update?","Version 1.09, Halloween & Guilds, released October 20, 2026, according to the Forge Wiki."),
      ("Is The Forge dying?","It's smaller than at launch but still active, with about 22,800 players online on November 11, 2026, and regular updates."),
      ("When did The Forge come out?","Version 1.00 released on November 27, 2025, according to the Forge Wiki's version history.")],
 sources=[F.wiki("Version_History","Version History"),F.wiki("Races"),("Roblox games API: The Forge live stats","https://games.roblox.com/v1/games?universeIds=7671049560")])
